def build_peptide_dataset(output_csv: str = "data/processed/quantum_peptide_dataset.csv") -> pd.DataFrame:
    all_sequences = AMP_SEQUENCES + ACP_SEQUENCES + ADP_SEQUENCES
    if len(all_sequences) != len(set(all_sequences)):
        raise ValueError("Duplicate sequences detected across categories! Clean sequences before compiling.")

    records = []
    categories = [
        ("AMP", 0, AMP_SEQUENCES),
        ("ACP", 1, ACP_SEQUENCES),
        ("ADP", 2, ADP_SEQUENCES),
    ]

    for class_name, label_id, seq_list in categories:
        for idx, seq in enumerate(seq_list, start=1):
            records.append({
                "Peptide_ID": f"{class_name}_{idx:03d}",
                "Sequence": seq,
                "Label_ID": label_id,
                "Class_Name": class_name,
                "PDB_Path": f"./structures/{class_name.lower()}_{idx:03d}.pdb",
            })

    df = pd.DataFrame(records)
    os.makedirs(os.path.dirname(output_csv), exist_ok=True)
    df.to_csv(output_csv, index=False)
    print(f"Saved {len(df)} unique peptide records to '{output_csv}'.")
    return df


if __name__ == "__main__":
    build_peptide_dataset()
